import {readFile,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
const phase=process.argv[2];if(!['dry-run','semantic-dry-run'].includes(phase))throw new Error('Only explicit rollback qualification supported by this revision');
const root='output/pdf-templates-full-20261005/acceptance-next';
const manifest=JSON.parse(await readFile(root+'/PAGE-ARBITER-QUALIFICATION.json','utf8'));
const vault=await readFile('./.private/CREDENTIALS.md','utf8');
const begin=vault.indexOf('<!-- FVI_CANONICAL_OPERATIONAL_CREDENTIALS_BEGIN -->'),end=vault.indexOf('<!-- FVI_CANONICAL_OPERATIONAL_CREDENTIALS_END -->');if(begin<0||end<=begin)throw new Error('FVI credential boundary missing');
const token=vault.slice(begin,end).split(/\r?\n/).find(x=>/^\|\s*`SUPABASE_ACCESS_TOKEN`\s*\|/.test(x))?.split('|')[2]?.trim().replace(/^`|`$/g,'');if(!/^sbp_/.test(token??''))throw new Error('FVI management authority missing');
const allowed={PROD:'YOUR_PROJECT_REF',DEV:'YOUR_PROJECT_REF'},sha=x=>createHash('sha256').update(x).digest('hex');
const identity="SELECT current_setting('server_version_num') AS engine,(SELECT count(*)::int FROM supabase_migrations.schema_migrations) AS ledger,(SELECT max(version::text) FROM supabase_migrations.schema_migrations) AS latest";
async function query(ref,sql,readonly){const response=await fetch('https://api.supabase.com/v1/projects/'+ref+'/database/query',{method:'POST',headers:{authorization:'Bearer '+token,'content-type':'application/json'},body:JSON.stringify({query:sql,read_only:readonly}),signal:AbortSignal.timeout(105000)});const raw=await response.text();if(!response.ok){const file='./LOCAL_USER/AppData/Local/FVI-QA-Private-20260925/FVI-PDF-INDEX-'+phase+'-ERROR-'+Date.now()+'.json';await writeFile(file,JSON.stringify({at:new Date().toISOString(),ref,http:response.status,raw},null,2),{flag:'wx'});throw new Error('PDF index HTTP'+response.status+'; private diagnostic saved');}return JSON.parse(raw);}
const results=[];
for(const plan of manifest.environments){if(allowed[plan.environment]!==plan.ref)throw new Error('Exact target mismatch');let sql=await readFile(root+'/'+plan.rollback_candidate.path,'utf8');if(sha(sql)!==plan.rollback_candidate.sha256||!sql.startsWith('BEGIN;\n')||!sql.endsWith('ROLLBACK;\n'))throw new Error('Exact rollback packet required');if(phase==='semantic-dry-run')sql=sql.slice(0,-'ROLLBACK;\n'.length)+(await readFile(root+'/NATIVE-PAGE-PURPOSE-CHECK.sql','utf8'))+'\nROLLBACK;\n';const before=(await query(plan.ref,identity,true))[0];if(before.engine!==plan.engine||before.ledger!==plan.ledger||before.latest!==plan.latest)throw new Error('Current engine/ledger changed; no DDL executed');const execution=await query(plan.ref,sql,false);const after=(await query(plan.ref,identity,true))[0];if(JSON.stringify(before)!==JSON.stringify(after))throw new Error('Unexpected post-rollback ledger difference');const file='./LOCAL_USER/AppData/Local/FVI-QA-Private-20260925/FVI-PDF-INDEX-'+plan.environment+'-'+phase+'-ROLLBACK-'+Date.now()+'.json';const receipt={at:new Date().toISOString(),environment:plan.environment,ref:plan.ref,sourceSha256:sha(sql),before,execution,after,committed:false,oldDataPreservationAssertedByExactSql:true,nativeSemanticCheck:phase==='semantic-dry-run'};await writeFile(file,JSON.stringify(receipt,null,2),{flag:'wx'});results.push({environment:plan.environment,ref:plan.ref,sourceSha256:sha(sql),ledger:after.ledger,latest:after.latest,rollbackPassed:true,committed:false,nativeSemanticCheck:phase==='semantic-dry-run',receipt:file});console.log(JSON.stringify(results.at(-1)));}
await writeFile('docs/evidence/FVI_PDF_INDEX_ROLLBACK_2026-10-05-'+Date.now()+'.json',JSON.stringify({at:new Date().toISOString(),phase,results,noApplicationDeployment:true},null,2),{flag:'wx'});
